// app/layout.tsx
import localFont from 'next/font/local';

// 1. Configure a local font file stored in the public/fonts directory
const myCustomFont = localFont({
  src: './fonts/MyBrandFont-Regular.woff2',
  weight: '400',
  style: 'normal',
  // Instructs Next.js to inject <link rel="preload"> into the HTML head
  // so the browser fetches the font before anything else!
  preload: true, 
});

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      {/* 2. Apply it globally via Tailwind CSS Variables! */}
      <body className={myCustomFont.className}>
        {children}
      </body>
    </html>
  );
}
